import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/SORT-VARIABLES.md","filePath":"manual-en/SORT-VARIABLES.md","lastUpdated":1785684581000}'),i={name:"manual-en/SORT-VARIABLES.md"};function s(n,e,l,p,A,d){return r(),t("div",null,[...e[0]||(e[0]=[o(`<h3 id="_11-5-sort-variables" tabindex="-1">11.5 SORT VARIABLES <a class="header-anchor" href="#_11-5-sort-variables" aria-label="Permalink to &quot;11.5 SORT VARIABLES&quot;">​</a></h3><p><code>SORT VARIABLES</code> reorders the variables in the active dataset’s dictionary according to a chosen sort key.</p><pre><code>SORT VARIABLES [BY]
    (NAME | TYPE | FORMAT | LABEL | VALUES | MISSING | MEASURE
     | ROLE | COLUMNS | ALIGNMENT | ATTRIBUTE name)
    [(D)].
</code></pre><p>The main specification is one of the following identifiers, which determines how the variables are sorted:</p><p>NAME</p><p>Sorts the variables according to their names, in a case-insensitive fashion. However, when variable names differ only in a number at the end, they are sorted numerically. For example, <code>VAR5</code> is sorted before <code>VAR400</code> even though ‘4’ precedes ‘5’.</p><p>TYPE</p><p>Sorts numeric variables before string variables, and shorter string variables before longer ones.</p><p>FORMAT</p><p>Groups variables by print format; within a format, sorts narrower formats before wider ones; with the same format and width, sorts fewer decimal places before more decimal places. See <a href="./FORMATS">FORMATS</a>.</p><p>LABEL</p><p>Sorts variables without a variable label before those with one. See <a href="./VARIABLE-LABELS">VARIABLE LABELS</a>.</p><p>VALUES</p><p>Sorts variables without value labels before those with some. See <a href="./VALUE-LABELS">VALUE LABELS</a>.</p><p>MISSING</p><p>Sorts variables without missing values before those with some. See <a href="./MISSING-VALUES">MISSING VALUES</a>.</p><p>MEASURE</p><p>Sorts nominal variables first, followed by ordinal variables, followed by scale variables. See <a href="./VARIABLE-LEVEL">VARIABLE LEVEL</a>.</p><p>ROLE</p><p>Groups variables according to their role. See <a href="./VARIABLE-ROLE">VARIABLE ROLE</a>.</p><p>COLUMNS</p><p>Sorts variables in ascending display width. See <a href="./VARIABLE-WIDTH">VARIABLE WIDTH</a>.</p><p>ALIGNMENT</p><p>Sorts variables according to their alignment, first left-aligned, then right-aligned, then centered. See <a href="./VARIABLE-ALIGNMENT">VARIABLE ALIGNMENT</a>.</p><p>ATTRIBUTE name</p><p>Sorts variables according to the first value of their name attribute. Variables without attribute are sorted first. See <a href="./VARIABLE-ATTRIBUTE">VARIABLE ATTRIBUTE</a>.</p><p>Only one sort criterion can be specified. The sort is “stable,” so to sort on multiple criteria one may perform multiple sorts. For example, the following will sort primarily based on alignment, with variables that have the same alignment ordered based on display width:</p><pre><code>SORT VARIABLES BY COLUMNS.
SORT VARIABLES BY ALIGNMENT.
</code></pre><p>Specify <code>(D)</code> to reverse the sort order.</p>`,29)])])}const E=a(i,[["render",s]]);export{h as __pageData,E as default};
